            if isinstance(obj, str) and obj == string:
                return True
            elif isinstance(obj, dict):
                return any(contains_string(v) for v in obj.values())
            elif isinstance(obj, list):
                return any(contains_string(item) for item in obj)
            return False
        if contains_string(data):
            result.append(os.path.abspath(file))
    return result

